def engine():
    global _ENGINE
    if _ENGINE is None:
        raw_bundle = base64.b85decode(PHYSICS_BUNDLE.encode("ascii"))
        assert hashlib.sha256(raw_bundle).hexdigest() == PHYSICS_BUNDLE_SHA256
        with zipfile.ZipFile(io.BytesIO(raw_bundle)) as archive:
            sources = {Path(name).stem: archive.read(name).decode("utf-8-sig") for name in archive.namelist()}
        # 先放入查找器，保证快照的传递依赖也来自同一版本。
        conflict = set(sources).intersection(sys.modules)
        if conflict:
            raise RuntimeError("物理快照模块已被别的入口导入，拒绝版本混用: " + str(sorted(conflict)))
        sys.meta_path.insert(0, FrozenLoader(sources))
        import train_uagmc_E0_E2_E6_effect_time_700k as core
        import train_uagmc_E3_E6_obs_topology_matrix_800k_FORMAL as mx
        import run_uagmc_6env_6baseline_36runs as rules
        _ENGINE = (core, mx, mx.base, rules)
    return _ENGINE


def legacy_modules(k):
    global _LEGACY
    engine()
    if _LEGACY is None:
        import train_uam_21x7_700k_ONEFILE_FINAL as old
        old.install_project_hooks()
        old._matrix_original_pair_virtual = old.v3._pair_virtual_features
        _LEGACY = old
    old = _LEGACY
    v3 = old.v3
    candidates = CANDIDATES[k]
    # 只泛化候选维数；K2保持原布局、网络和公式。
    for module in (v3, v3.legacy, old.v4, old.v5):
        if hasattr(module, "CANDIDATES"):
            module.CANDIDATES = tuple(candidates)
    v3.N_CANDIDATES = k
    v3.NUM_FRAMES = 6
    v3.SINGLE_FRAME_DIM = 4 + 8 * k
    v3.BASE_OBS_DIM = 6 * v3.SINGLE_FRAME_DIM
    v3.RESOURCE_DIM = 8 * k + 4
    v3.SHARED_DIM = v3.SRAC_DIM = v3.CQM_DIM = 10 * k
    v3.GAMMA_DIM = 10 * k * len(v3.GAMMA_HORIZONS)
    v3.EVENT_DIM = k * 4 * v3.MAX_EVENTS_PER_TYPE
    v3.TDM_DIM = 5 * k
    v3.FIRST_DIM = 5 * k
    v3.TAU_DIM = k
    v3.PAIR_VIRTUAL_DIM = k * k * 4
    for name in ("SINGLE_FRAME_DIM", "BASE_OBS_DIM", "RESOURCE_DIM", "SHARED_DIM"):
        if hasattr(v3.legacy, name):
            setattr(v3.legacy, name, getattr(v3, name))
    v3.EnvSpec.n_actions = property(lambda spec: k * k if spec.joint else k)
    if k == 3:
        def pair_virtual(scenario, spec, tau):
            if not spec.joint:
                return [0.] * (k * k * 4)
            output = []
            eligible = v3._eligible_hub_count(scenario) > 0
            for p in range(k):
                # 同一乘客候选的只读投影不依赖飞机动作，只计算一次。
                projection = v3._project(scenario, spec, candidates[p], tau[p])
                for a in range(k):
                    own = projection
                    demand, supply = own[1] + 1., own[5] + float(eligible and p == a)
                    output.extend([tau[p], demand, supply, demand / (1. + supply)])
            return output
        v3._pair_virtual_features = pair_virtual
    else:
        v3._pair_virtual_features = old._matrix_original_pair_virtual
    v3.GLOBAL_LAYOUT = v3.make_layout()
    return old


def corrected_reward():
    core, mx, base, _ = engine()
    from at_obj.scenario import Scenario
    method = Scenario.step
    if getattr(method, "_matrix_corrected", False):
        base._ORIG_SCENARIO_STEP = method
        return
    source = textwrap.dedent(inspect.getsource(method))
    start = source.find("active_count_start = sum(")
    stop = source.find("reward = -float(active_count_start)", start)
    if start < 0 or stop < 0:
        raise RuntimeError("Scenario.step奖励结构未通过核验，不能猜测替换")
    indent = source[source.rfind("\n", 0, start) + 1:start]
    replacement = ("_matrix_finished_set = set(self.finished_ids)\n" + indent +
                   "active_count_start = sum(pid not in _matrix_finished_set "
                   "for pid in self.persons.persons)\n" + indent)
    source = source[:start] + replacement + source[stop:]
    namespace = {}
    module = sys.modules[Scenario.__module__]
    exec(compile(source, "<corrected_person_time>", "exec"), module.__dict__, namespace)
    Scenario.step = namespace["step"]
    Scenario.step._matrix_corrected = True
    base._ORIG_SCENARIO_STEP = Scenario.step


def locate_file(text):
    path = Path(str(text))
    if path.is_file():
        return path.resolve()
    parts = str(text).replace("\\", "/").split("/")
    # 冻结文件可能记录Windows绝对路径；按工程内相同相对位置解析，随后核对hash。
    for marker in ("train_data", "test_data", "data", "serial_runs"):
        if marker in parts:
            candidate = ROOT.joinpath(*parts[parts.index(marker):])
            if candidate.is_file():
                return candidate.resolve()
    # 本地清理过原trace目录时，从原件的只读备份恢复到本实验自己的输入目录。
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(INPUTS_BUNDLE.encode("ascii")))) as archive:
        matches = [name for name in archive.namelist() if Path(name).name == Path(str(text).replace("\\", "/")).name]
        if len(matches) == 1:
            folder = Path(os.environ.get("UAM_MATRIX_INPUT_ROOT", ROOT / "serial_runs" / "uam_E123_K23_HAPPO_132_v1" / "inputs"))
            destination = folder / Path(matches[0]).name
            if not destination.exists():
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(archive.read(matches[0]))
            return destination.resolve()
    raise FileNotFoundError("冻结输入未找到: " + str(text))


def freeze_document(arg=None):
    choices = [Path(arg)] if arg else [ROOT / "UAM_FINAL_FREEZE_V2.json"] + list(
        (ROOT / "serial_runs").rglob("UAM_FINAL_FREEZE_V2.json"))
    required = dict(n_envs=10, n_steps=2048, global_rollout=20480, batch_size=4096,
                    n_epochs=10, initial_lr=5e-4, gamma=1.0, gae_lambda=.95,
                    clip_range=.25, ent_coef=.01, vf_coef=.5, max_grad_norm=.5)
    valid = []
    if not any(path.is_file() for path in choices):
        choices.append(locate_file("UAM_FINAL_FREEZE_V2.json"))
    for path in choices:
        if not path.is_file():
            continue
        document = read_json(path)
        if document.get("schema") != "UAM_FINAL_FREEZE_V2":
            continue
        config = document.get("frozen_ppo", {})
        if any(k not in config or not math.isclose(float(config[k]), v, abs_tol=1e-9) for k, v in required.items()):
            continue
        if config.get("lr_schedule") != "linear_from_initial_to_zero_over_each_full_run":
            continue
        env = document.get("frozen_environment", {})
        demand = document.get("demand_protocol", {})
        if (env.get("topology"), env.get("fleet_size"), env.get("selected_load")) != ("T2", 40, 1.0):
            continue
        if demand.get("selected_protocol") != "FIXED_TRACE":
            continue
        digest_file = path.with_suffix(".sha256")
        digest = digest_file.read_text().split()[0].lower() if digest_file.is_file() else CANONICAL_FREEZE_SHA256
        if digest != sha(path):
            continue
        train = locate_file(env["selected_trace"])
        heldout = [locate_file(p) for p in demand["heldout_trace_bank"]]
        if len(heldout) != 4 or len(set(sha(p) for p in [train] + heldout)) != 5:
            raise RuntimeError("训练与四条验证trace必须是五份不同输入")
        for lock in demand.get("heldout_trace_locks", []) + demand.get("train_trace_locks", []):
            if sha(locate_file(lock["path"])) != lock["sha256"]:
                raise RuntimeError("需求hash与V2锁不一致")
        valid.append((path.stat().st_mtime, path, document, train, heldout))
    if not valid:
        raise RuntimeError("未找到完整V2原锁，拒绝更改物理/奖励/训练数据后冒称冻结实验")
    _, path, doc, train, bank = max(valid, key=lambda entry: entry[0])
    return dict(original=str(path), original_sha256=sha(path), document=doc,
                train=str(train), bank=[str(p) for p in bank],
                train_sha256=sha(train), bank_sha256=[sha(p) for p in bank])



def dispatch_priority(self):
    """统一执行器：飞机动作只改变合法缺口的优先级，不改变物理权限。"""
    _, _, base, _ = engine()
    candidates = CANDIDATES[self._matrix_k]
    hub = str(self.fixed_fleet_return_vertiport)
    available = sorted((e for e in self.vertiports.evtols_at_vertiport.get(hub, [])
                        if e.state.name == "IDLE" and not e.passenger_ids
                        and not base.is_turnaround_busy(e)), key=lambda e: str(e.id))
    # 与旧K2一致：按现有等候队列逐架扣减；不新增供给扣除/跨站回收权限。
    deficits = {v: len(self.vertiports.vertiport_list[str(v)].person_list) for v in candidates}
    stats = dict(eligible=len(available), attempts=0, successes=0, blocked=0,
                 priority_overrides=0, zero_queue_departures=0, serviced_targets=[])
    requested = candidates[int(getattr(self, "_matrix_air_priority", 0))]
    for aircraft in available:
        positive = [vid for vid in candidates if deficits[vid] > 0]
        if not positive:
            break
        if self._matrix_control != "LQ" and requested in positive:
            destination = requested
        else:
            destination = max(positive, key=lambda vid: (deficits[vid], -vid))
            stats["priority_overrides"] += int(self._matrix_control != "LQ" and destination != requested)
        # 每次成功必须消耗一个缺口；不能重复补足同一乘客的运力。
        assert len(self.vertiports.vertiport_list[str(destination)].person_list) > 0
        stats["attempts"] += 1
        if not base._start_empty_reposition_checked(
                scenario=self, evtol=aircraft, origin=hub, destination=str(destination)):
            stats["blocked"] += 1
            break
        stats["successes"] += 1
        stats["serviced_targets"].append(destination)
        deficits[destination] -= 1
    self._matrix_dispatch = stats



class JointExecutor(gym.Wrapper):
    def __init__(self, env, k, control):
        super().__init__(env)
        self.k, self.control = k, control
        self.action_space = spaces.Discrete(k if control == "LQ" else k * k)
        self._install()

    def _install(self):
        _, mx, _, _ = engine()
        self.scenario = mx.find_scenario(self.env)
        self.scenario._matrix_k = self.k
        self.scenario._matrix_control = self.control
        self.scenario._matrix_air_priority = 0
        self.scenario._dispatch_fixed_returns = types.MethodType(dispatch_priority, self.scenario)

    def reset(self, **kwargs):
        result = self.env.reset(**kwargs)
        self._install()
        return result

    def step(self, action):
        raw = int(action)
        if not self.action_space.contains(raw):
            raise ValueError("动作越界")
        passenger, aircraft = (raw, 0) if self.control == "LQ" else divmod(raw, self.k)
        self.scenario._matrix_air_priority = aircraft
        output = self.env.step(passenger)
        obs, reward, terminated, truncated, info = output
        info = dict(info)
        info["matrix_dispatch"] = dict(getattr(self.scenario, "_matrix_dispatch", {}))
        return obs, reward, terminated, truncated, info


def layout_for(k):
    original = legacy_modules(k).v3.GLOBAL_LAYOUT
    return dict(dims=original["dims"], slices=original["slices"], total=original["total_dim"], k=k, frame=4 + 8 * k)




class MatrixNormalize(VecNormalize):
    """沿用旧合同：只有物理tau不做观测归一化。"""
    def normalize_obs(self, obs):
        raw = np.asarray(obs)
        result = super().normalize_obs(obs)
        # 此对象固定服务一个候选维数；缓存槽位边界，不反复注册整个布局。
        if getattr(self, "_tau_cache_k", None) != self.k:
            self._tau_cache_k = self.k
            self._tau_cache_slice = layout_for(self.k)["slices"]["tau"]
        layout = {"slices": {"tau": self._tau_cache_slice}}
        for name in ("tau",):
            lo, hi = layout["slices"][name]
            result[..., lo:hi] = raw[..., lo:hi]
        return result


def make_env(environment, k, control, trace, directory, index=0):
    core, mx, base, _ = engine()
    torch.set_num_threads(1)
    corrected_reward()
    mx.TURNAROUND_DELAY_MIN = 1.0
    base.TURNAROUND_DELAY_MIN = 1.0
    core.TURNAROUND_DELAY_MIN = 1.0
    core.TRAIN_FILE = Path(trace)
    mx.MAX_TIME = GUARD
    base.MAX_TIME = GUARD
    from at_obj.vertiport.vertiport_spec import VERTIPORT_CHARGE_RATE
    import at_obj.evtol.evtol_builder as aircraft_builder
    # 用绝对值设置，禁止spawn/续训时重复乘以充电倍率。
    for vid, rate in {"0": 10.64, "1": 5.32, "2": 5.32, "3": 5.32}.items():
        VERTIPORT_CHARGE_RATE[vid] = rate * 1.25
        aircraft_builder.VERTIPORT_CHARGE_RATE[vid] = rate * 1.25
    raw = core.make_experiment_env_factory(stage=PHYSICAL[environment], topology="T" + str(k),
        encoder_mode="uagmc", fleet_size=40, env_index=index, run_dir=Path(directory),
        pad_separation=0.0, charger_capacity=5, max_time=GUARD)()
    old = legacy_modules(k)
    key = old.key_for(environment, control)
    old.register_spec(environment, control)
    if k == 2:
        # 所有K2控制都沿用原V5物理权限；HAPPO改变更新器，不改变飞机执行器。
        if control != "LQ":
            raw = old.v5.CleanMinimalJointWrapper(raw, key)
    else:
        raw = JointExecutor(raw, k, control)
    env = old.v3.LiteratureObservationWrapper(raw, env_key=key, method_id="UAGMC_OD_BASE")
    # 空间、航线、充电率、维数只来自环境，无为各方法单独设置参数。
    return env


class MatchedRepresentation(BaseFeaturesExtractor):
    """前四种直接用旧源码表示；只对两个新增方法和K维数做所需适配。"""
    def __init__(self, observation_space, features_dim=128, k=2, method="UAGMC_OD_BASE", n_actions=2,
                 control="LQ", environment="E3"):
        super().__init__(observation_space, features_dim)
        old = legacy_modules(k)
        key = old.key_for(environment, control)
        old.register_spec(environment, control)
        self.k, self.method, self.n_actions = k, method, n_actions
        self.layout = old.v3.GLOBAL_LAYOUT
        if method in ("UAGMC_OD_BASE", "UAGMC_A_TRANSFER", "SA_LITE"):
            self.backbone = old.UAGMCODExtractor(observation_space, features_dim, self.layout, "UAGMC_OD_BASE", key)
        else:
            self.backbone = old.ng.NextGenExtractor(observation_space, features_dim=features_dim,
                layout=self.layout, method_id=method, env_key=key)
        if method == "UAGMC_A_TRANSFER":
            self.attention_frame = nn.Sequential(nn.Linear(4 + 8 * k, 128), nn.ReLU())
            self.cls = nn.Parameter(torch.zeros(1, 1, 128))
            layer = nn.TransformerEncoderLayer(128, 2, 256, dropout=0., batch_first=True,
                                              norm_first=True, activation="relu")
            self.attention = nn.TransformerEncoder(layer, 1, enable_nested_tensor=False)
            position = torch.arange(7).float().unsqueeze(1)
            divisor = torch.exp(torch.arange(0, 128, 2).float() * (-math.log(10000.) / 128))
            encoding = torch.zeros(7, 128)
            encoding[:, 0::2], encoding[:, 1::2] = torch.sin(position * divisor), torch.cos(position * divisor)
            self.register_buffer("position", encoding[None])
        elif method == "SA_LITE":
            self.lite = nn.Sequential(nn.Linear(20 * k, 64), nn.ReLU(), nn.Linear(64, 64), nn.ReLU())
            self.lite_fuse = nn.Sequential(nn.Linear(192, 160), nn.ReLU(), nn.Linear(160, 128))

    def sl(self, obs, name):
        lo, hi = self.layout["slices"][name]
        return obs[:, lo:hi]

    def forward(self, observations):
        obs = observations.float()
        if self.method == "UAGMC_A_TRANSFER":
            frames = self.sl(obs, "base").reshape(-1, 6, 4 + 8 * self.k)
            tokens = self.attention_frame(frames)
            tokens = torch.cat([self.cls.expand(len(obs), -1, -1), tokens], 1) + self.position
            temporal = self.backbone.output_proj(self.attention(tokens)[:, 0])
            extra = self.backbone.focal_resource(torch.cat([self.sl(obs, "resource"), self.sl(obs, "focal")], -1))
            return self.backbone.fuse(torch.cat([temporal, extra], -1))
        base = self.backbone(obs)
        if self.method == "SA_LITE":
            simple = self.lite(torch.cat([self.sl(obs, "shared"), self.sl(obs, "srac")], -1))
            return self.lite_fuse(torch.cat([base, simple], -1))
        return base

    def icm_z(self, observations):
        return self.backbone.icm_z(observations)

    @property
    def icm_inverse(self):
        return self.backbone.icm_inverse

    def ac_parameters(self):
        return self.backbone.aux_parameters_for("A_ICM_AC")


class Factory:
    def __init__(self, environment, k, control, trace, directory, index):
        self.args = environment, k, control, trace, directory, index

    def __call__(self):
        return make_env(*self.args)



def head(width, outputs):
    return nn.Sequential(nn.Linear(width, 256), nn.ReLU(), nn.Linear(256, 256), nn.ReLU(), nn.Linear(256, outputs))


class MatrixPolicy(ActorCriticPolicy):
    """三种既有联合actor与真正独立参数的HAPPO actor/central critic。"""
    def __init__(self, *args, k=2, control="LQ", method="UAGMC_OD_BASE", **kwargs):
        self.k, self.control, self.method = k, control, method
        environment = kwargs.pop("environment", "E3")
        kwargs["features_extractor_class"] = MatchedRepresentation
        kwargs["features_extractor_kwargs"] = dict(k=k, method=method, n_actions=k if control == "LQ" else k * k,
                                                  control=control, environment=environment)
        kwargs["ortho_init"] = False
        super().__init__(*args, **kwargs)

    def _build(self, lr_schedule):
        k = self.k
        if self.control == "HAPPO":
            self.p_encoder = self.features_extractor
            self.a_encoder = self.make_features_extractor()
            self.v_encoder = self.make_features_extractor()
            self.p_head, self.a_head = head(128, k), head(128, k)
        else:
            self.p_encoder = self.features_extractor
            self.a_encoder = self.p_encoder
            self.v_encoder = self.p_encoder
            self.p_head, self.a_head = head(128, k), head(128, k)
        self.conditional = head(128 + k, k)
        self.gate = head(128, k * k)
        self.value_net = head(128, 1)
        self.optimizer = self.optimizer_class(self.parameters(), lr=lr_schedule(1), **self.optimizer_kwargs)
        if self.control == "HAPPO":
            p = list(self.p_encoder.parameters()) + list(self.p_head.parameters())
            a = list(self.a_encoder.parameters()) + list(self.a_head.parameters())
            v = list(self.v_encoder.parameters()) + list(self.value_net.parameters())
            assert not set(map(id, p)).intersection(map(id, a))
            assert not set(map(id, p + a)).intersection(map(id, v)), "HAPPO actor与critic禁止共享梯度参数"
            self.actor_optimizers = [torch.optim.Adam(p, lr=lr_schedule(1), eps=1e-5),
                                     torch.optim.Adam(a, lr=lr_schedule(1), eps=1e-5)]
            self.critic_optimizer = torch.optim.Adam(v, lr=lr_schedule(1), eps=1e-5)

    def masks(self, obs):
        # 保留旧合同的标准PPO信用口径：物理gate不等于额外的策略mask。
        legal = torch.ones((len(obs), self.k), device=obs.device, dtype=torch.bool)
        return legal, legal

    def side_dist(self, obs, side):
        encoder = self.p_encoder if side == 0 else self.a_encoder
        output = self.p_head if side == 0 else self.a_head
        logits = output(encoder(obs))
        mask = self.masks(obs)[side]
        return Categorical(logits=logits.masked_fill(~mask, -1e9))

    def get_distribution(self, obs):
        latent = self.p_encoder(obs)
        p, a = self.p_head(latent), self.a_head(self.a_encoder(obs) if self.control == "HAPPO" else latent)
        pm, am = self.masks(obs)
        p = p.masked_fill(~pm, -1e9)
        a = a.masked_fill(~am, -1e9)
        if self.control == "LQ":
            logits = p
        elif self.control == "J3":
            logp, rows = F.log_softmax(p, -1), []
            for index in range(self.k):
                one = F.one_hot(torch.full((len(obs),), index, device=obs.device), self.k).float()
                conditional = self.conditional(torch.cat([latent, one], -1)).masked_fill(~am, -1e9)
                rows.append(logp[:, index:index + 1] + F.log_softmax(conditional, -1))
            logits = torch.stack(rows, 1).flatten(1)
        else:
            logits = p.unsqueeze(2) + a.unsqueeze(1)
            if self.control == "J4":
                logits = logits + .25 * self.gate(latent).reshape(-1, self.k, self.k)
            logits = logits.flatten(1)
        return self.action_dist.proba_distribution(action_logits=logits)

    def predict_values(self, obs):
        return self.value_net(self.v_encoder(obs))

    def forward(self, obs, deterministic=False):
        distribution = self.get_distribution(obs)
        actions = distribution.get_actions(deterministic=deterministic)
        return actions.reshape((-1, *self.action_space.shape)), self.predict_values(obs), distribution.log_prob(actions)

    def evaluate_actions(self, obs, actions):
        distribution = self.get_distribution(obs)
        return self.predict_values(obs), distribution.log_prob(actions.long().flatten()), distribution.entropy()

    def _predict(self, obs, deterministic=False):
        return self.get_distribution(obs).get_actions(deterministic=deterministic)


class AbsolutePPO(PPO):
    """中断续训使用总预算的绝对LR进度，禁止重新启动线性学习率。"""
    absolute_horizon = TOTAL

    def _update_current_progress_remaining(self, num_timesteps, total_timesteps):
        self._current_progress_remaining = max(0., 1. - num_timesteps / self.absolute_horizon)

    def _ac_pairs(self):
        buffer = self.rollout_buffer
        obs, actions, starts = buffer.observations, buffer.actions, buffer.episode_starts
        if obs.ndim != 3:
            raise RuntimeError("辅助学习必须在PPO打平rollout之前提取相邻状态")
        times, envs = np.where(starts[1:] < .5)
        if not len(times):
            return None
        if len(times) > 12000:
            selection = np.random.choice(len(times), 12000, replace=False)
            times, envs = times[selection], envs[selection]
        # 保留上面的随机抽样顺序；非AC方法不需要把状态对复制到GPU。
        if self.policy.method not in ("A_ICM_AC", "SA_TDMFUSION_ICM"):
            return None
        return (torch.as_tensor(obs[times, envs], dtype=torch.float32, device=self.device),
                torch.as_tensor(obs[times + 1, envs], dtype=torch.float32, device=self.device),
                torch.as_tensor(actions[times, envs, 0], dtype=torch.long, device=self.device))

    def _auxiliary(self, pairs, encoders):
        if pairs is None or self.policy.method not in ("A_ICM_AC", "SA_TDMFUSION_ICM"):
            return
        cur, nxt, actions = pairs
        if not hasattr(self, "ac_optimizers"):
            self.ac_optimizers = {}
        values = []
        for tag, encoder in encoders:
            if tag not in self.ac_optimizers:
                self.ac_optimizers[tag] = torch.optim.Adam(encoder.ac_parameters(), lr=.001)
            optimizer = self.ac_optimizers[tag]
            for indices in torch.randperm(len(cur), device=self.device).split(2048):
                predicted = encoder.icm_inverse(torch.cat([encoder.icm_z(cur[indices]), encoder.icm_z(nxt[indices])], -1))
                loss = F.cross_entropy(predicted, actions[indices])
                optimizer.zero_grad(set_to_none=True)
                loss.backward()
                nn.utils.clip_grad_norm_(encoder.ac_parameters(), 5.)
                optimizer.step()
                values.append(float(loss.detach().cpu()))
        if values:
            self.logger.record("train/icm_inverse_loss", float(np.mean(values)))

    def train(self):
        pairs = self._ac_pairs()
        if self.policy.control != "HAPPO":
            self._auxiliary(pairs, [("shared", self.policy.features_extractor)])
            super().train()
            return
        self._happo_train(pairs)

    def _happo_train(self, pairs):
        # 此顺序与HARL一致：整轮更新一个actor，更新factor，再更新下一个actor，最后critic。
        self.policy.set_training_mode(True)
        buffer = self.rollout_buffer
        def flatten(array):
            return torch.as_tensor(buffer.swap_and_flatten(array), device=self.device, dtype=torch.float32)
        obs = flatten(buffer.observations)
        actions = flatten(buffer.actions).long().flatten()
        advantages = flatten(buffer.advantages[..., None]).flatten()
        advantages = (advantages - advantages.mean()) / (advantages.std(unbiased=False) + 1e-5)
        returns = flatten(buffer.returns[..., None]).flatten()
        values_old = flatten(buffer.values[..., None]).flatten()
        factor = torch.ones(len(obs), device=self.device)
        side_actions = [actions // self.policy.k, actions % self.policy.k]
        # rollout阶段关闭dropout，取样概率与更新前概率一致；必须在辅助loss更新前保存。
        with torch.no_grad():
            old_log = [torch.cat([self.policy.side_dist(obs[ix], side).log_prob(side_actions[side][ix])
                                 for ix in torch.arange(len(obs), device=self.device).split(BATCH)])
                       for side in range(2)]
        lr = float(self.lr_schedule(self._current_progress_remaining))
        clip = float(self.clip_range(self._current_progress_remaining))
        logs, entropies, ratios = [], [], []
        order = torch.randperm(2).tolist()
        for side in order:
            encoder = self.policy.p_encoder if side == 0 else self.policy.a_encoder
            output = self.policy.p_head if side == 0 else self.policy.a_head
            self._auxiliary(pairs, [("actor" + str(side), encoder)])
            optimizer = self.policy.actor_optimizers[side]
            for group in optimizer.param_groups:
                group["lr"] = lr
            for _ in range(self.n_epochs):
                for ix in torch.randperm(len(obs), device=self.device).split(self.batch_size):
                    distribution = self.policy.side_dist(obs[ix], side)
                    logp = distribution.log_prob(side_actions[side][ix])
                    ratio = torch.exp(logp - old_log[side][ix])
                    loss = -(factor[ix] * torch.minimum(ratio * advantages[ix],
                            ratio.clamp(1 - clip, 1 + clip) * advantages[ix])).mean()
                    entropy = distribution.entropy().mean()
                    optimizer.zero_grad(set_to_none=True)
                    (loss - self.ent_coef * entropy).backward()
                    nn.utils.clip_grad_norm_(list(encoder.parameters()) + list(output.parameters()), self.max_grad_norm)
                    optimizer.step()
                    logs.append(float(loss.detach().cpu()))
                    entropies.append(float(entropy.detach().cpu()))
            with torch.no_grad():
                new_log = torch.cat([self.policy.side_dist(obs[ix], side).log_prob(side_actions[side][ix])
                                     for ix in torch.arange(len(obs), device=self.device).split(BATCH)])
                update_ratio = torch.exp(new_log - old_log[side])
                factor = factor * update_ratio
                if not torch.isfinite(factor).all():
                    raise FloatingPointError("HAPPO重要性factor非有限；保留失败记录，不进行人为裁剪")
                ratios.append(float(update_ratio.mean().cpu()))
        self._auxiliary(pairs, [("critic", self.policy.v_encoder)])
        optimizer = self.policy.critic_optimizer
        for group in optimizer.param_groups:
            group["lr"] = lr
        value_losses = []
        for _ in range(self.n_epochs):
            for ix in torch.randperm(len(obs), device=self.device).split(self.batch_size):
                values = self.policy.predict_values(obs[ix]).flatten()
                loss = F.mse_loss(values, returns[ix])
                optimizer.zero_grad(set_to_none=True)
                (self.vf_coef * loss).backward()
                nn.utils.clip_grad_norm_(list(self.policy.v_encoder.parameters()) + list(self.policy.value_net.parameters()),
                                         self.max_grad_norm)
                optimizer.step()
                value_losses.append(float(loss.detach().cpu()))
        self._n_updates += self.n_epochs
        self.logger.record("train/policy_gradient_loss", float(np.mean(logs)))
        self.logger.record("train/entropy_loss", -float(np.mean(entropies)))
        self.logger.record("train/value_loss", float(np.mean(value_losses)))
        self.logger.record("train/happo_factor_mean", float(factor.mean().cpu()))
        self.logger.record("train/happo_agent_order", str(order))
        self.logger.record("train/explained_variance", explained_variance(values_old.cpu().numpy(), returns.cpu().numpy()))
        self.logger.record("train/learning_rate", lr)
        self.logger.record("train/n_updates", self._n_updates)


class GenericJointPolicy(ActorCriticPolicy):
    """沿用J0/J3/J4的原计算，仅把两个输出泛化为K个。"""
    def __init__(self, *args, k=2, joint_arch="J0", **kwargs):
        self.k, self.joint_arch = k, joint_arch
        schedule = kwargs.get("lr_schedule", args[2] if len(args) >= 3 else None)
        super().__init__(*args, **kwargs)
        d = self.mlp_extractor.latent_dim_pi
        self.action_net = nn.Identity()
        self.p_head = nn.Sequential(nn.Linear(d, 64), nn.ReLU(), nn.Linear(64, k))
        self.a_head = nn.Sequential(nn.Linear(d, 64), nn.ReLU(), nn.Linear(64, k))
        self.cond_a = nn.Sequential(nn.Linear(d + k, 64), nn.ReLU(), nn.Linear(64, k))
        self.mappo_shared = nn.Sequential(nn.Linear(d, 96), nn.Tanh(), nn.Linear(96, 64), nn.Tanh())
        self.mappo_p, self.mappo_a = nn.Linear(64, k), nn.Linear(64, k)
        self.mappo_gate = nn.Sequential(nn.Linear(64, 32), nn.ReLU(), nn.Linear(32, k * k))
        self.optimizer = self.optimizer_class(self.parameters(), lr=schedule(1), **self.optimizer_kwargs)

    def _get_action_dist_from_latent(self, latent_pi):
        x, k = latent_pi, self.k
        if self.joint_arch == "J0":
            logits = self.p_head(x).unsqueeze(2) + self.a_head(x).unsqueeze(1)
        elif self.joint_arch == "J3":
            p = F.log_softmax(self.p_head(x), -1)
            rows = []
            for i in range(k):
                one = F.one_hot(torch.full((len(x),), i, device=x.device), k).float()
                a = F.log_softmax(self.cond_a(torch.cat([x, one], -1)), -1)
                rows.append(p[:, i:i + 1] + a)
            logits = torch.stack(rows, 1)
        elif self.joint_arch == "J4":
            h = self.mappo_shared(x)
            logits = self.mappo_p(h).unsqueeze(2) + self.mappo_a(h).unsqueeze(1) + .25 * self.mappo_gate(h).reshape(-1, k, k)
        else:
            raise ValueError(self.joint_arch)
        return self.action_dist.proba_distribution(action_logits=logits.flatten(1))


def attach_policy(model, cell):
    model.policy.control = cell[2]
    model.policy.method = cell[3]
    model.policy.k = cell[1]
    return model


def save_pair(model, norm, directory, step):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    # 原子对：只有模型、归一化、优化器/RNG三份都完成才发布索引。
    stem = f"checkpoint_{step}"
    model.save(directory / (stem + ".model.tmp.zip"))
    norm.save(directory / (stem + ".norm.tmp.pkl"))
    state = dict(random=random.getstate(), numpy=np.random.get_state(), torch=torch.get_rng_state(),
                 cuda=torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None,
                 ac={k: v.state_dict() for k, v in getattr(model, "ac_optimizers", {}).items()},
                 actors=[optimizer.state_dict() for optimizer in getattr(model.policy, "actor_optimizers", [])],
                 critic=getattr(model.policy, "critic_optimizer", None).state_dict()
                         if hasattr(model.policy, "critic_optimizer") else None)
    torch.save(state, directory / (stem + ".state.tmp.pt"))
    for kind, suffix in (("model", "zip"), ("norm", "pkl"), ("state", "pt")):
        (directory / f"{stem}.{kind}.tmp.{suffix}").replace(directory / f"{stem}.{kind}.{suffix}")
    write_json(directory / (stem + ".json"), dict(step=step, ready=True,
               model=stem + ".model.zip", norm=stem + ".norm.pkl", state=stem + ".state.pt"))


def checkpoints(directory):
    result = []
    for path in (Path(directory) / "checkpoints").glob("checkpoint_*.json"):
        data = read_json(path)
        if data.get("ready") and all((path.parent / data[key]).is_file() for key in ("model", "norm", "state")):
            result.append((int(data["step"]), path.parent / data["model"], path.parent / data["norm"], path.parent / data["state"]))
    return sorted(result)


class EvidenceCallback(BaseCallback):
    def __init__(self, directory):
        super().__init__()
        self.directory = Path(directory)
        self.last = -1

    def _on_step(self):
        if self.n_calls % 1280 == 0:
            write_json(self.directory / "heartbeat.json", dict(time=utc(), pid=os.getpid(), phase="TRAIN",
                                                               transitions=self.num_timesteps))
        return True

    def _on_rollout_start(self):
        # 在上一次完整PPO更新之后存储，避免检查点是“采样完但更新未完成”。
        step = int(self.model.num_timesteps)
        if step > 0 and step % PERIOD == 0 and step != self.last:
            save_pair(self.model, self.training_env, self.directory / "checkpoints", step)
            self.last = step


def linear_rate(progress):
    return .0005 * max(0., float(progress))


def contract(cell, frozen, args):
    return dict(version=VERSION, cell=cell, seed=args.seed, steps=TOTAL, n_envs=N_ENVS,
                n_steps=N_STEPS, batch=BATCH, epochs=EPOCHS, lr_initial=.0005,
                lr_horizon=TOTAL, gamma=1., gae_lambda=.95, clip=.25, entropy=.01,
                vf=.5, max_grad=.5, guard=GUARD, fleet=40, turn=1., charger=5,
                charging_scale=1.25, pad=0., reward=REWARD_MARKER,
                kernel="K2原V5_CLEAN；K3按正队列优先级泛化，空目标回退到正队列",
                initial_fleet="K2原始30/10；K3沿用已验证20/10/10；总机队40不变",
                freeze_sha256=frozen["original_sha256"], trace_sha256=frozen["train_sha256"],
                bank_sha256=frozen["bank_sha256"], code_sha256=sha(Path(__file__)),
                engine_sha256=PHYSICS_BUNDLE_SHA256,
                native_hashes=native_hashes(), framework=torch.__version__, device=args.device)


def native_hashes():
    paths = ["at_obj/scenario.py", "at_obj/scenario_fixed_fleet.py", "utilss/uam_rl_wrapper.py",
             "utilss/make_env_fleet.py", "at_obj/evtol/evtol.py", "at_obj/person/person.py"]
    return {name: sha(ROOT / name) for name in paths if (ROOT / name).is_file()}


def restore_state(model, path):
    state = torch.load(path, map_location="cpu", weights_only=False)
    for optimizer, stored in zip(getattr(model.policy, "actor_optimizers", []), state.get("actors", [])):
        optimizer.load_state_dict(stored)
    if state.get("critic") is not None:
        model.policy.critic_optimizer.load_state_dict(state["critic"])
    model.ac_optimizers = {}
    encoders = ({"actor0": model.policy.p_encoder, "actor1": model.policy.a_encoder, "critic": model.policy.v_encoder}
                if model.policy.control == "HAPPO" else {"shared": model.policy.features_extractor})
    for name, stored in state.get("ac", {}).items():
        optimizer = torch.optim.Adam(encoders[name].ac_parameters(), lr=.001)
        optimizer.load_state_dict(stored)
        model.ac_optimizers[name] = optimizer
    random.setstate(state["random"])
    np.random.set_state(state["numpy"])
    torch.set_rng_state(state["torch"])
    if torch.cuda.is_available() and state.get("cuda"):
        torch.cuda.set_rng_state_all(state["cuda"])


def train_cell(cell, directory, frozen, args):
    environment, k, control, method = cell
    worker_start = time.monotonic()
    directory = Path(directory)
    expected = clean(contract(cell, frozen, args))
    old = read_json(directory / "contract.json")
    if old is not None and old != expected:
        raise RuntimeError("此cell已有不同训练合同，拒绝混入或覆盖")
    write_json(directory / "contract.json", expected)
    end = read_json(directory / "train_end.json", {})
    if end.get("status") == "COMPLETE":
        return
    torch.set_num_threads(1)
    random.seed(args.seed)
    np.random.seed(args.seed)
    torch.manual_seed(args.seed)
    raw = SubprocVecEnv([Factory(environment, k, control, frozen["train"], str(directory), index)
                        for index in range(N_ENVS)], start_method="spawn")
    raw.seed(args.seed)
    norm = None
    start_time = time.monotonic()
    model = None
    try:
        pairs = checkpoints(directory)
        initial = pairs[-1][0] if pairs else 0
        if pairs:
            _, model_path, norm_path, state_path = pairs[-1]
            norm = MatrixNormalize.load(norm_path, raw)
            model = attach_policy(AbsolutePPO.load(model_path, env=norm, device=args.device), cell)
            restore_state(model, state_path)
            model._last_obs = None
            model._last_episode_starts = None
            print(f"[续训] {cell} {initial}/{TOTAL}；LR保持绝对horizon，模拟器重新reset", flush=True)
        else:
            norm = MatrixNormalize(raw, norm_obs=True, norm_reward=True, gamma=1., clip_obs=10., clip_reward=10.)
            norm.k = k
            if control == "HAPPO":
                policy = MatrixPolicy
                policy_kwargs = dict(k=k, control=control, method=method, environment=environment)
            else:
                policy = "MlpPolicy" if control == "LQ" else GenericJointPolicy
                policy_kwargs = dict(features_extractor_class=MatchedRepresentation,
                    features_extractor_kwargs=dict(k=k, method=method, environment=environment, control=control,
                                                  n_actions=k if control == "LQ" else k * k),
                    net_arch=dict(pi=[256, 256], vf=[256, 256]))
                if control != "LQ":
                    policy_kwargs.update(k=k, joint_arch=control)
            model = AbsolutePPO(policy, norm, learning_rate=linear_rate, n_steps=N_STEPS,
                batch_size=BATCH, n_epochs=EPOCHS, gamma=1., gae_lambda=.95, clip_range=.25,
                ent_coef=.01, vf_coef=.5, max_grad_norm=.5, target_kl=None, seed=args.seed,
                device=args.device, verbose=1, tensorboard_log=str(directory / "tb"),
                policy_kwargs=policy_kwargs)
            attach_policy(model, cell)
        model.absolute_horizon = TOTAL
        write_json(directory / "model_capacity.json", dict(parameters=sum(p.numel() for p in model.policy.parameters()),
                   control=control, method=method, k=k, independent_actors=control == "HAPPO",
                   critic_shared_parameters=control != "HAPPO",
                   note="HAPPO独立编码器有额外参数与计算量；不宣称不同控制器完全容量匹配"))
        print(f"[START] {cell_name(cell)} {initial}/{TOTAL} device={args.device} "
              f"parameters={sum(p.numel() for p in model.policy.parameters())} deferred_eval=True", flush=True)
        setup_seconds = time.monotonic() - worker_start
        learn_started = time.monotonic()
        if initial < TOTAL:
            model.learn(TOTAL - initial, reset_num_timesteps=initial == 0, callback=EvidenceCallback(directory))
        learn_seconds = time.monotonic() - learn_started
        assert model.num_timesteps == TOTAL
        save_started = time.monotonic()
        save_pair(model, norm, directory / "checkpoints", TOTAL)
        write_json(directory / "TRAIN_TIMING.json", dict(created=utc(), resumed_from=initial,
                   new_transitions=TOTAL - initial, setup_seconds=setup_seconds,
                   learn_seconds=learn_seconds, final_save_seconds=time.monotonic() - save_started,
                   learn_effective_fps=(TOTAL - initial) / learn_seconds if learn_seconds else None,
                   note="learn包含周期检查点保存；父进程总耗时另见last_train_process.json"))
        write_json(directory / "train_end.json", dict(status="COMPLETE", actual_steps=TOTAL,
                   resumed_from=initial, segment_seconds=time.monotonic() - start_time, finished_at=utc()))
    finally:
        if norm is not None:
            norm.close()
        else:
            raw.close()


def metrics(scenario, reward_sum, steps, dispatch, action_counts):
    _, mx, _, _ = engine()
    snapshot = mx.snapshot_episode(scenario)
    rows = snapshot["rows"]
    # 冻结主指标只允许全体完成；记录完整人表，不能靠completed-only把均值压低。
    finished_ids = set(map(str, scenario.finished_ids))
    complete = len(finished_ids) == len(rows) and bool(rows) and all(finite(row["travel_time"]) for row in rows)
    def mean(key):
        return float(np.mean([float(row[key]) for row in rows])) if complete and all(finite(row[key]) for row in rows) else None
    aircraft = []
    for ev in scenario._all_evtols.values():
        aircraft.append(dict(id=ev.id, state=ev.state.name, current=str(ev.current_vertiport_id),
                             target=str(ev.target_vertiport_id), battery=ev.battery_kwh,
                             remaining=ev.remaining_time, turnaround=bool(getattr(ev, "_e345_turnaround_busy", False))))
    all_idle = all(row["state"] == "IDLE" and not row["turnaround"] for row in aircraft)
    stranded = all_idle and any(value > 0 for value in snapshot["queues"].values()) and not any(row["current"] == "2" for row in aircraft)
    return dict(full=complete, ATT=mean("travel_time"), AWT=mean("wait"), AGT=mean("access"), AFT=mean("fly"),
                N=len(rows), finished=len(finished_ids), completion=len(finished_ids) / max(1, len(rows)),
                person_time_per_generated=-float(reward_sum) / max(1, len(rows)),
                simulation_steps=steps, unfinished=len(rows) - len(finished_ids),
                stranded_all_idle=stranded, dispatch=dispatch, action_counts=action_counts,
                terminal_resources=dict(queues=snapshot["queues"], fleet=snapshot.get("fleet_diag"),
                                        stages=snapshot.get("stage_stats"), aircraft=aircraft), passengers=rows)


_REPLAY_MODEL_CACHE = None
_REPLAY_LOAD_SECONDS = 0.0
_REPLAY_LOAD_COUNT = 0


def replay_model(cell, model_path):
    """一个worker最多缓存一个检查点模型，避免同bank重复创建PPO与rollout buffer。"""
    global _REPLAY_MODEL_CACHE, _REPLAY_LOAD_SECONDS, _REPLAY_LOAD_COUNT
    path = Path(model_path)
    key = (tuple(cell), str(path.resolve()), path.stat().st_mtime_ns)
    if _REPLAY_MODEL_CACHE is None or _REPLAY_MODEL_CACHE["key"] != key:
        load_started = time.monotonic()
        model = attach_policy(AbsolutePPO.load(path, device="cpu"), cell)
        _REPLAY_LOAD_SECONDS += time.monotonic() - load_started
        _REPLAY_LOAD_COUNT += 1
        # PPO.load会重置随机数；缓存后每次回放仍恢复该调用完成时的状态。
        # 不能只省略load，否则STO和含随机过程的环境可能换一套随机数协议。
        _REPLAY_MODEL_CACHE = dict(key=key, model=model,
            python_state=random.getstate(), numpy_state=np.random.get_state(),
            torch_state=torch.get_rng_state().clone())
    entry = _REPLAY_MODEL_CACHE
    random.setstate(entry["python_state"])
    np.random.set_state(entry["numpy_state"])
    torch.set_rng_state(entry["torch_state"])
    return entry["model"]


def replay(cell, directory, frozen, step, pair, trace, eval_seed, stochastic=False, rule=None):
    environment, k, control, method = cell
    mode = "STO" if stochastic else "DET"
    cache = Path(directory) / "analysis" / "episodes" / f"{rule or mode}_{step}_{sha(trace)[:12]}_{eval_seed}.json"
    old = read_json(cache)
    if old is not None:
        return old
    raw = make_env(environment, k, control, trace, directory, 9999)
    vec = DummyVecEnv([lambda: raw])
    norm = None
    try:
        norm = MatrixNormalize.load(pair[2], vec) if pair else None
        if norm:
            norm.training = False
            norm.norm_reward = False
            assert norm.observation_space.shape == raw.observation_space.shape
        obs, _ = raw.reset(seed=eval_seed)
        _, mx, _, rules = engine()
        scenario = mx.find_scenario(raw)
        model = replay_model(cell, pair[1]) if pair else None
        torch.manual_seed(eval_seed)
        reward_sum, steps = 0., 0
        dispatch = dict(attempts=0, successes=0, blocked=0, priority_overrides=0)
        counts = [0] * k
        timeline = []
        while True:
            if rule:
                action, _ = rules.choose_action(raw, PHYSICAL[environment], "T" + str(k), rule, 5, 60.)
            else:
                action, _ = model.predict(norm.normalize_obs(obs), deterministic=not stochastic)
                action = int(np.asarray(action).item())
            uam = mx.find_uam_wrapper(raw)
            if (uam.state or {}).get("waiting_decisions"):
                counts[action if control == "LQ" else action // k] += 1
            obs, reward, terminated, truncated, info = raw.step(action)
            reward_sum += float(reward)
            steps += 1
            for key in dispatch:
                physical = info.get("matrix_dispatch", {})
                mapped = {"attempts": "v5_dispatch_attempts", "successes": "v5_dispatch_successes", "blocked": "v5_dispatch_blocked"}
                dispatch[key] += int(physical.get(key, info.get(mapped.get(key, "__none__"), 0)))
            if steps % 25 == 0:
                timeline.append(dict(time=scenario.time, queues={vid: len(v.person_list) for vid, v in scenario.vertiports.vertiport_list.items()},
                                     ready_hub=sum(e.state.name == "IDLE" for e in scenario.vertiports.evtols_at_vertiport.get("2", [])),
                                     charging=sum(e.state.name == "CHARGING" for e in scenario._all_evtols.values())))
            if terminated or truncated:
                break
            if steps > GUARD + 3:
                raise RuntimeError("仿真没有遵守hard guard，拒绝无限回放")
        result = metrics(scenario, reward_sum, steps, dispatch, counts)
        result.update(cell=cell, step=step, trace=str(trace), eval_seed=eval_seed, mode=rule or mode,
                      train_seed=read_json(Path(directory) / "contract.json", {}).get("seed"),
                      timeline=timeline, created=utc())
        write_json(cache, result)
        return result
    finally:
        if norm:
            norm.close()
        else:
            vec.close()


def summary_of(directory, dense, bank):
    valid = [row for row in dense if row.get("full") and finite(row.get("ATT"))]
    late = [row for row in dense if row["step"] >= .8 * TOTAL]
    bank_valid = len(bank) == 32 and all(row.get("full") and finite(row.get("ATT")) for row in bank)
    best = min((row["ATT"] for row in valid), default=None)
    late_bank_points = []
    for step in sorted(set(row["step"] for row in bank)):
        group = [row for row in bank if row["step"] == step]
        if len(group) == 8 and all(row.get("full") and finite(row.get("ATT")) for row in group):
            late_bank_points.append(dict(step=step, ATT=float(np.mean([row["ATT"] for row in group]))))
    values = [row["ATT"] for row in late_bank_points]
    lw = float(np.mean(values)) if bank_valid else None
    result = dict(status="VALID" if bank_valid else "INCOMPLETE_OR_MISSING_EVAL", LWATT=lw,
                  Final=late_bank_points[-1]["ATT"] if bank_valid else None, dense_best=best,
                  dense_final=dense[-1].get("ATT") if dense else None,
                  late_sd=float(np.std(values, ddof=1)) if bank_valid and len(values) > 1 else None,
                  late_slope_per_100k=float(np.polyfit([row["step"] / 1e5 for row in late_bank_points], values, 1)[0])
                  if bank_valid and len(values) > 1 else None,
                  dense_Best_to_Late=(float(np.mean([row["ATT"] for row in late])) - best) / best
                  if best and late and all(row.get("full") for row in late) else None,
                  bank_episodes=len(bank), bank_incomplete=sum(not row.get("full") for row in bank),
                  bank_min_completion=min((row.get("completion", 0) for row in bank), default=0),
                  cross_training_seed_stability="单训练seed，不作推断")
    write_json(Path(directory) / "analysis" / "summary.json", result)
    write_csv(Path(directory) / "analysis" / "dense_curve.csv", dense)
    write_csv(Path(directory) / "analysis" / "late_bank.csv", bank)
    return result


def eval_cell(cell, directory, frozen, args):
    eval_started = time.monotonic()
    pairs = checkpoints(directory)
    if not pairs or pairs[-1][0] != TOTAL:
        raise RuntimeError("未完成训练，仍保留已有检查点，但不生成满训正式排名")
    dense, bank, errors = [], [], []
    for pair in pairs:
        step = pair[0]
        tasks = [(frozen["bank"][0], 123)]
        if step >= .8 * TOTAL:
            tasks = [(trace, seed) for trace in frozen["bank"] for seed in (123, 124)]
        for trace, seed in tasks:
            write_json(Path(directory) / "heartbeat.json", dict(time=utc(), phase="EVAL", checkpoint=step, trace=trace, seed=seed))
            try:
                result = replay(cell, directory, frozen, step, pair, trace, seed)
                compact = {key: result.get(key) for key in ("step", "ATT", "AWT", "AGT", "AFT", "full", "completion",
                           "simulation_steps", "dispatch", "action_counts", "stranded_all_idle", "trace", "eval_seed")}
            except Exception:
                compact = dict(step=step, ATT=None, full=False, trace=trace, eval_seed=seed, error=traceback.format_exc())
                errors.append(compact)
            if trace == frozen["bank"][0] and seed == 123:
                dense.append(compact)
            if step >= .8 * TOTAL:
                bank.append(compact)
            print(f"[回放] {cell} {step} seed={seed} ATT={compact.get('ATT')} completion={compact.get('completion')}", flush=True)
    # STO只在末点同一bank作诊断，不替代或择优覆盖DET主表。
    sto = []
    for trace in frozen["bank"]:
        for seed in (123, 124):
            try:
                result = replay(cell, directory, frozen, TOTAL, pairs[-1], trace, seed, stochastic=True)
                sto.append({key: result.get(key) for key in ("ATT", "AWT", "completion", "full", "trace", "eval_seed", "action_counts")})
            except Exception:
                failure = dict(ATT=None, full=False, mode="STO", trace=trace, eval_seed=seed,
                               error=traceback.format_exc())
                sto.append(failure)
                errors.append(failure)
    write_csv(Path(directory) / "analysis" / "stochastic_final_bank.csv", sto)
    write_json(Path(directory) / "analysis" / "errors.json", errors)
    result = summary_of(directory, dense, bank)
    write_json(Path(directory) / "EVAL_TIMING.json", dict(created=utc(),
               total_seconds=time.monotonic() - eval_started,
               model_load_seconds=_REPLAY_LOAD_SECONDS, model_load_count=_REPLAY_LOAD_COUNT,
               checkpoints=len(pairs), dense_points=len(dense), bank_episodes=len(bank),
               stochastic_episodes=len(sto), errors=len(errors),
               note="CPU回放；缓存命中的episode不重复仿真；与训练耗时分开记录"))
    write_json(Path(directory) / "eval_end.json", dict(status="COMPLETE", summary_status=result["status"], finished_at=utc()))


def reference_rules(environment, k, root, frozen):
    directory = Path(root) / "references" / f"{environment}_K{k}"
    rows = []
    for rule in ("SPF", "STTF", "QTTI2", "CSM", "ECTF", "MPTC"):
        for trace in frozen["bank"]:
            for seed in (123, 124):
                try:
                    result = replay((environment, k, "LQ", "RULE"), directory, frozen, 0, None, trace, seed, rule=rule)
                    rows.append({key: result.get(key) for key in ("ATT", "AWT", "AGT", "AFT", "full", "completion", "trace", "eval_seed", "mode")})
                except Exception:
                    rows.append(dict(mode=rule, trace=trace, eval_seed=seed, ATT=None, full=False, error=traceback.format_exc()))
    write_csv(directory / "rule_episodes.csv", rows)
    aggregates = []
    for rule in ("SPF", "STTF", "QTTI2", "CSM", "ECTF", "MPTC"):
        group = [row for row in rows if row["mode"] == rule]
        full = len(group) == 8 and all(row.get("full") for row in group)
        aggregates.append(dict(rule=rule, full=full, ATT=float(np.mean([row["ATT"] for row in group])) if full else None,
                               comparison="同bank解析启发式，非数学下界；飞机自动LQ权限"))
    write_csv(directory / "rule_summary.csv", aggregates)
    write_json(directory / "done.json", dict(status="COMPLETE", summaries=aggregates))


def cell_name(cell):
    environment, k, control, method = cell
    return f"{environment}__K{k}__{control}__{method}"


def run_worker(command, logfile, hard_hours):
    logfile = Path(logfile)
    logfile.parent.mkdir(parents=True, exist_ok=True)
    # 子进程建立独立会话；超时只终止本脚本创建的进程组，不影响共享服务器别人任务。
    kwargs = {"start_new_session": True} if os.name != "nt" else {}
    start = time.monotonic()
    with logfile.open("a", encoding="utf-8") as file:
        file.write("\n[LAUNCH " + utc() + "] " + " ".join(command) + "\n")
        file.flush()
        process = subprocess.Popen(command, cwd=ROOT, stdout=file, stderr=subprocess.STDOUT, **kwargs)
        try:
            while process.poll() is None:
                if time.monotonic() - start > hard_hours * 3600:
                    if os.name == "nt":
                        process.terminate()
                    else:
                        os.killpg(process.pid, signal.SIGTERM)
                    try:
                        process.wait(timeout=30)
                    except subprocess.TimeoutExpired:
                        if os.name == "nt":
                            process.kill()
                        else:
                            os.killpg(process.pid, signal.SIGKILL)
                    raise TimeoutError("此cell达到明确硬超时；已终止自己创建的进程组，保留检查点")
                time.sleep(1)
        except KeyboardInterrupt:
            if os.name == "nt":
                process.terminate()
            else:
                os.killpg(process.pid, signal.SIGTERM)
            raise
    if process.returncode and os.name != "nt":
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
    return process.returncode, time.monotonic() - start


# =============================================================================
# 本轮补充入口：不调用历史父矩阵入口，也不改原矩阵的结果目录。
# =============================================================================
SUPPLEMENT_BUDGET = 60000000
SUPPLEMENT_ROOT = "serial_runs/uam_K2K3_supp60m_focus_v2"
PRIMARY_ROOT = "serial_runs/uam_E123_K23_HAPPO_132_v1"


def supplement_specs():
    """原一亿矩阵的重点重复确认：42条件各追加602/603，共84个新run。"""
    specs = []
    schedule_rng = random.Random(20261014)
    # 桥接4个run：让每种候选规模的UAGMC/LQ拥有完整E1→E2→E3阶梯。
    for k in (2, 3):
        for seed in (602, 603):
            specs.append(dict(family="P0_BRIDGE4", cell=["E1", k, "LQ", "UAGMC_OD_BASE"], seed=seed))
    # 核心64个run：同环境/规模/seed内，八个方法×控制对照作为一个完整配对块。
    # 排程随机数只改变运行次序，绝不修改PPO的训练随机种子。
    for environment in ("E3", "E2"):
        for k in (2, 3):
            for seed in (602, 603):
                block = [dict(family="P1_CORE64", cell=[environment, k, control, method], seed=seed)
                         for control in ("LQ", "J0")
                         for method in ("UAGMC_OD_BASE", "S_TDM_EVENT_FUSION", "A_ICM_AC", "SA_TDMFUSION_ICM")]
                schedule_rng.shuffle(block)
                specs.extend(block)
    # J4和真实HAPPO分别用完整基线/方法对确认，不只重复有利的低ATT模型。
    for family, control, methods in (
        ("P2_J4_8", "J4", ("UAGMC_OD_BASE", "SA_TDMFUSION_ICM")),
        ("P3_HAPPO8", "HAPPO", ("UAGMC_OD_BASE", "A_ICM_AC")),
    ):
        for k in (2, 3):
            for seed in (602, 603):
                block = [dict(family=family, cell=["E3", k, control, method], seed=seed) for method in methods]
                schedule_rng.shuffle(block)
                specs.extend(block)
    keys = {(tuple(spec["cell"]), spec["seed"]) for spec in specs}
    conditions = {tuple(spec["cell"]) for spec in specs}
    assert len(specs) == len(keys) == 84
    assert len(conditions) == 42
    assert all({spec["seed"] for spec in specs if tuple(spec["cell"]) == cell} == {602, 603}
               for cell in conditions)
    assert len(specs) * TOTAL == 58490880 <= SUPPLEMENT_BUDGET
    return specs


def supplement_name(spec):
    return cell_name(spec["cell"]) + "__s" + str(spec["seed"])


def resolve_root(text):
    path = Path(text)
    return path.resolve() if path.is_absolute() else (ROOT / path).resolve()


def supplement_inputs(primary, destination, explicit_freeze=None):
    """父实验的冻结原件只读；跨机器路径仅按内容哈希重新定位。"""
    frozen = read_json(destination / "INPUTS_LOCK.json")
    if frozen is None:
        frozen = read_json(primary / "INPUTS_LOCK.json")
        if frozen is None:
            frozen = freeze_document(explicit_freeze)
    frozen = copy.deepcopy(frozen)
    if frozen["original_sha256"] != CANONICAL_FREEZE_SHA256:
        raise RuntimeError("冻结原锁不同，不能与昨天矩阵混排")
    frozen["train"] = str(locate_file(frozen["train"]))
    frozen["bank"] = [str(locate_file(path)) for path in frozen["bank"]]
    pairs = [(frozen["train"], frozen["train_sha256"])] + list(zip(frozen["bank"], frozen["bank_sha256"]))
    if len(pairs) != 5 or len(set(digest for _, digest in pairs)) != 5:
        raise RuntimeError("训练和四条验证trace必须不同且完整")
    for path, digest in pairs:
        if sha(path) != digest:
            raise RuntimeError("输入内容发生变化：" + path)
    return frozen


def primary_snapshot(primary):
    """只读记录旧矩阵状态；缺格、失败和缺回放都写入报告，不能填成完成。"""
    plan = read_json(primary / "PLAN.json", {})
    if not plan:
        raise FileNotFoundError("未找到父矩阵PLAN.json：" + str(primary))
    required = dict(code_sha256=PARENT_SOURCE_SHA256, engine_sha256=PHYSICS_BUNDLE_SHA256,
                    freeze_sha256=CANONICAL_FREEZE_SHA256, actual_steps_per_cell=TOTAL, seed=601)
    for key, value in required.items():
        if plan.get(key) != value:
            raise RuntimeError("父矩阵合同不一致：" + key)
    rows = []
    for directory in sorted((primary / "cells").glob("*")):
        summary = read_json(directory / "analysis" / "summary.json", {})
        stored = read_json(directory / "contract.json", {})
        rows.append(dict(cell=directory.name, configuration=stored.get("cell"),
                         training=read_json(directory / "train_end.json", {}).get("status", "PENDING"),
                         evaluation=read_json(directory / "eval_end.json", {}).get("status", "PENDING"),
                         source="PRIMARY_SEED601", **summary))
    return dict(created=utc(), primary_root=str(primary), plan=plan,
                progress=read_json(primary / "progress.json", {}),
                parent_session_end=read_json(primary / "SESSION_END.json", {}), rows=rows)


def supplement_export(root, specs, primary=None):
    rows = []
    for index, spec in enumerate(specs):
        directory = root / "cells" / supplement_name(spec)
        summary = read_json(directory / "analysis" / "summary.json", {})
        rows.append(dict(index=index, family=spec["family"], cell=cell_name(spec["cell"]),
                         train_seed=spec["seed"], run=supplement_name(spec),
                         training=read_json(directory / "train_end.json", {}).get("status", "PENDING"),
                         evaluation=read_json(directory / "eval_end.json", {}).get("status", "PENDING"),
                         source="SUPPLEMENT", **summary))
    write_csv(root / "MATRIX_RESULTS.csv", rows)
    write_json(root / "progress.json", dict(time=utc(), planned=84, planned_steps=84 * TOTAL,
              trained=sum(row["training"] == "COMPLETE" for row in rows),
              evaluated=sum(row["evaluation"] == "COMPLETE" for row in rows),
              valid=sum(row.get("status") == "VALID" for row in rows),
              actual_saved_steps=sum(read_json(root / "cells" / row["run"] / "train_end.json", {}).get("actual_steps", 0)
                                     for row in rows), rows=rows))
    previous = read_json(root / "PRIMARY_READONLY_SNAPSHOT.json", {})
    # 旧48格采用父矩阵内的历史schema，保留原字段，不假装逐项完全等价。
    combined = list(previous.get("rows", [])) + rows
    write_csv(root / "PRIMARY_PLUS_SUPPLEMENT.csv", combined)
    # 训练seed才是独立单位；4条trace×2回放seed先在run内汇总。
    grouping = {}
    for row in combined:
        config = row.get("configuration")
        if config is None and row.get("source") == "SUPPLEMENT":
            config = specs[row["index"]]["cell"]
        if not config or row.get("status") != "VALID" or not finite(row.get("LWATT")):
            continue
        key = tuple(config)
        seed = row.get("train_seed", 601)
        grouping.setdefault(key, {})[seed] = row
    aggregates = []
    for key, by_seed in sorted(grouping.items()):
        values = [float(row["LWATT"]) for row in by_seed.values()]
        n = len(values)
        average = float(np.mean(values))
        sd = float(np.std(values, ddof=1)) if n > 1 else None
        aggregates.append(dict(environment=key[0], k=key[1], control=key[2], method=key[3],
                              n_train_seeds=n, seeds=sorted(by_seed), LWATT_mean=average,
                              n_new_seeds=sum(row.get("source") == "SUPPLEMENT" for row in by_seed.values()),
                              n_reused_parent=sum(row.get("training") == "REUSED_COMPLETE" for row in by_seed.values()),
                              LWATT_sd=sd, LWATT_cv=sd / average if sd is not None and average else None,
                              worst=max(values), best_seed_value=min(values),
                              interpretation="描述性复核；父/补训代码版本及检查点保存边界分别保留，不作显著性检验"))
    write_csv(root / "PAIRED_SEED_SUMMARY.csv", aggregates)


def supplement_archive(root, primary):
    """只打包数据、配置、日志和本脚本；不包含任何模型/优化器/归一化pickle。"""
    destination = ROOT / "experiment_archives" / (root.name + "_DATAONLY.tar.gz")
    destination.parent.mkdir(parents=True, exist_ok=True)
    suffixes = {".json", ".csv", ".log", ".txt", ".md", ".sha256"}
    with tarfile.open(destination, "w:gz") as archive:
        for path in sorted(root.rglob("*")):
            if not path.is_file() or path.suffix.lower() not in suffixes:
                continue
            if path.name == ".SUPPLEMENT_RUNNING.json":
                continue
            if "tb" in path.relative_to(root).parts:
                continue
            archive.add(path, arcname=str(Path(root.name) / path.relative_to(root)))
        # 父实验只附比较所需汇总，不复制其整套权重和逐乘客回放缓存。
        if primary.is_dir():
            for path in sorted(primary.rglob("*")):
                if not path.is_file():
                    continue
                rel = path.relative_to(primary)
                if "tb" in rel.parts or "episodes" in rel.parts or "checkpoints" in rel.parts:
                    continue
                if path.name in {"PLAN.json", "INPUTS_LOCK.json", "MATRIX_RESULTS.csv", "progress.json",
                                 "summary.json", "dense_curve.csv", "late_bank.csv",
                                 "stochastic_final_bank.csv", "rule_summary.csv", "rule_episodes.csv",
                                 "model_capacity.json", "contract.json", "train_end.json", "eval_end.json"}:
                    archive.add(path, arcname=str(Path(root.name) / "primary_reference" / rel))
        archive.add(Path(__file__), arcname=root.name + "/" + Path(__file__).name)
    print("[数据包]", destination, destination.stat().st_size, "bytes；无权重", flush=True)


def supplement_lock(root):
    """避免两次补训同时写同一目录；绝不自动终止旧实验或他人进程。"""
    import socket
    lock = root / ".SUPPLEMENT_RUNNING.json"
    host = socket.gethostname()
    try:
        previous = read_json(lock, {})
    except json.JSONDecodeError as exc:
        raise RuntimeError("运行锁正在写入或格式异常，拒绝重复开训；请先核实自己的任务") from exc
    if previous:
        if previous.get("host") != host:
            raise RuntimeError("目录有另一主机的运行锁，需人工确认，不自动删除")
        try:
            pid = int(previous["pid"])
            if pid <= 0:
                raise ValueError("运行锁PID必须为正整数")
            os.kill(pid, 0)
        except ProcessLookupError:
            # 只回收同一主机且明确已不存在的本实验锁。
            lock.unlink(missing_ok=True)
        except (ValueError, KeyError) as exc:
            raise RuntimeError("运行锁PID异常，不自动覆盖") from exc
        except PermissionError:
            raise RuntimeError("无法核实运行锁，不抢占")
        else:
            raise RuntimeError("本补训已在运行，PID=" + str(previous["pid"]))
    try:
        # 排队命令误执行两次时，独占创建保证只有一个父进程能获得锁。
        with lock.open("x", encoding="utf-8") as file:
            json.dump(dict(pid=os.getpid(), host=host, created=utc()), file, ensure_ascii=False)
            file.flush()
            os.fsync(file.fileno())
    except FileExistsError as exc:
        raise RuntimeError("另一补训进程已经抢先取得运行锁，本进程不会重复训练") from exc
    return lock


def supplement_execute(root, specs, args, phase, only_indices=None):
    selected = range(len(specs)) if only_indices is None else only_indices
    # 先训完这一轮，再统一评估；不在GPU训练中间插入回放。
    for index in selected:
        spec = specs[index]
        directory = root / "cells" / supplement_name(spec)
        end = read_json(directory / (phase + "_end.json"), {})
        if end.get("status") == "COMPLETE":
            # 物理删失是已完成评价，不反复重跑；技术异常的回放允许续跑补齐。
            technical_errors = read_json(directory / "analysis" / "errors.json", []) if phase == "eval" else []
            if not technical_errors:
                continue
        if phase == "eval" and read_json(directory / "train_end.json", {}).get("status") != "COMPLETE":
            continue
        command = [sys.executable, "-u", str(Path(__file__).resolve()), "--output-root", str(root),
                   "--primary-root", str(args.primary_root), "--device", args.device,
                   "--seed", str(spec["seed"]), "--worker", phase, "--cell", str(index)]
        print(f"[{phase.upper()} {index + 1}/84] {supplement_name(spec)}", flush=True)
        started = utc()
        try:
            code, elapsed = run_worker(command, directory / (phase + ".log"), args.hard_hours)
            write_json(directory / ("last_" + phase + "_process.json"),
                       dict(phase=phase, started=started, finished=utc(),
                            elapsed_seconds=elapsed, exit_code=code, fresh_seed=spec["seed"]))
            if code:
                print("[失败跳过]", supplement_name(spec), "退出码", code, flush=True)
        except Exception:
            write_json(directory / (phase + "_launch_failure.json"),
                       dict(time=utc(), traceback=traceback.format_exc()))
            print("[启动失败跳过]", supplement_name(spec), flush=True)
        supplement_export(root, specs)


def main():
    parser = argparse.ArgumentParser(description="原矩阵之后的84run/58.49M补充实验")
    parser.add_argument("--output-root", default=SUPPLEMENT_ROOT)
    parser.add_argument("--primary-root", default=PRIMARY_ROOT)
    parser.add_argument("--freeze")
    parser.add_argument("--device", choices=("cuda", "cpu"), default="cuda")
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--phase", choices=("all", "train", "eval"), default="all")
    parser.add_argument("--archive-only", action="store_true")
    parser.add_argument("--hard-hours", type=float, default=8.)
    parser.add_argument("--worker", choices=("train", "eval", "rules"), help=argparse.SUPPRESS)
    parser.add_argument("--cell", type=int, help=argparse.SUPPRESS)
    parser.add_argument("--seed", type=int, default=602, help=argparse.SUPPRESS)
    args = parser.parse_args()
    root, primary = resolve_root(args.output_root), resolve_root(args.primary_root)
    args.primary_root = str(primary)
    os.environ.setdefault("UAM_MATRIX_INPUT_ROOT", str(root / "inputs"))
    specs = supplement_specs()
    if args.archive_only:
        supplement_archive(root, primary)
        return
    if root == primary:
        raise RuntimeError("补训结果目录不能等于昨天矩阵，禁止覆盖历史")
    if args.worker:
        frozen = supplement_inputs(primary, root, args.freeze)
        spec = specs[args.cell]
        if args.seed != spec["seed"]:
            raise RuntimeError("worker随机种子与预注册cell不符")
        directory = root / "cells" / supplement_name(spec)
        directory.mkdir(parents=True, exist_ok=True)
        try:
            if args.worker == "train":
                train_cell(spec["cell"], directory, frozen, args)
            elif args.worker == "eval":
                eval_cell(spec["cell"], directory, frozen, args)
            else:
                reference_rules(spec["cell"][0], spec["cell"][1], root, frozen)
        except Exception:
            write_json(directory / (args.worker + "_failure.json"),
                       dict(time=utc(), status="FAILED", traceback=traceback.format_exc()))
            raise
        return
    if args.device == "cuda" and not torch.cuda.is_available():
        raise RuntimeError("CUDA不可用；不静默退到CPU")
    if root.exists() and any(root.iterdir()) and not args.resume:
        raise FileExistsError("已有输出；续训请加--resume，不覆盖")
    root.mkdir(parents=True, exist_ok=True)
    lock = supplement_lock(root)
    start = time.monotonic()
    try:
        frozen = supplement_inputs(primary, root, args.freeze)
        plan = dict(version=VERSION, specs=specs, cells=84, distinct_conditions=42,
                    planned_training_seeds=[602, 603], schedule_seed=20261014,
                    paired_blocks="同环境/候选规模/训练seed内完整配对；块内固定随机排程",
                    steps_per_run=TOTAL,
                    total_new_training_steps=84 * TOTAL, budget_upper=SUPPLEMENT_BUDGET,
                    engine_sha256=PHYSICS_BUNDLE_SHA256, code_sha256=sha(Path(__file__)),
                    native_hashes=native_hashes(), parent_source_sha256=PARENT_SOURCE_SHA256,
                    freeze_sha256=frozen["original_sha256"], train_sha256=frozen["train_sha256"],
                    bank_sha256=frozen["bank_sha256"], n_envs=N_ENVS, n_steps=N_STEPS,
                    batch=BATCH, epochs=EPOCHS, source_weights="不加载旧权重，全部从零训练",
                    optimizations=["未完成人数名单只建集合一次", "K3每个乘客候选投影只算一次",
                                   "归一化槽位缓存", "非AC不复制状态对到GPU且保留抽样随机序列",
                                   "父进程轮询从10秒改1秒", "单检查点模型缓存并恢复原load随机数副作用"],
                    contract="物理/奖励/观测数值/网络/PPO顺序与父矩阵一致；不是位级复现保证")
        old = read_json(root / "PLAN.json")
        if old is not None and old != clean(plan):
            raise RuntimeError("补训PLAN不同，禁止混入；请使用相同文件和命令续训")
        write_json(root / "PLAN.json", plan)
        if not (root / "INPUTS_LOCK.json").is_file():
            write_json(root / "INPUTS_LOCK.json", frozen)
            write_json(root / "ORIGINAL_V2_READONLY_COPY.json", frozen["document"])
        snapshot = primary_snapshot(primary)
        write_json(root / "PRIMARY_READONLY_SNAPSHOT.json", snapshot)
        if snapshot["progress"].get("evaluated", 0) < 180:
            print("[证据提示] 父矩阵仍有未评估/失败格，保留状态；本轮不按缺失ATT择优", flush=True)
        write_csv(root / "CELL_PLAN.csv", [dict(index=i, family=spec["family"],
                  run=supplement_name(spec), environment=spec["cell"][0], k=spec["cell"][1],
                  control=spec["cell"][2], method=spec["cell"][3], seed=spec["seed"], steps=TOTAL)
                  for i, spec in enumerate(specs)])
        if args.phase != "eval":
            supplement_execute(root, specs, args, "train")
        if args.phase != "train":
            # 规则基线共享同一LQ权限，不能称作所有Joint控制的数学下界。
            seen = set()
            for i, spec in enumerate(specs):
                key = tuple(spec["cell"][:2])
                if key in seen:
                    continue
                seen.add(key)
                done = read_json(root / "references" / f"{key[0]}_K{key[1]}" / "done.json", {})
                if done.get("status") == "COMPLETE":
                    continue
                command = [sys.executable, "-u", str(Path(__file__).resolve()), "--output-root", str(root),
                           "--primary-root", str(primary), "--device", args.device,
                           "--seed", str(spec["seed"]), "--worker", "rules", "--cell", str(i)]
                try:
                    code, elapsed = run_worker(command, root / "references" / f"{key[0]}_K{key[1]}" / "rules.log",
                                               args.hard_hours)
                    write_json(root / "references" / f"{key[0]}_K{key[1]}" / "process.json",
                               dict(exit_code=code, elapsed_seconds=elapsed, finished=utc()))
                except Exception:
                    write_json(root / "references" / f"{key[0]}_K{key[1]}" / "failure.json",
                               dict(traceback=traceback.format_exc(), created=utc()))
            supplement_execute(root, specs, args, "eval")
        supplement_export(root, specs)
        write_json(root / "SESSION_END.json", dict(time=utc(), phase=args.phase,
                   elapsed_seconds=time.monotonic() - start, total_planned_steps=84 * TOTAL))
        supplement_archive(root, primary)
        print("[结束] 新84run/58.49M，旧矩阵只读；完整状态见progress.json", flush=True)
    finally:
        # 只移除自己的轻量锁；任何训练结果与旧文件均不删除。
        if read_json(lock, {}).get("pid") == os.getpid():
            lock.unlink(missing_ok=True)


